// CSD_RATIONALE_BEGIN
// Lazy-close symbolic CSD for grade-school math word problems.
//
// Prior failure root cause: CloseConstrainedSpan was called as soon as
// parser.IsCompletePrefix became true — which happens after a SINGLE variable
// token (e.g., `n`, `price`). The model exploited this by writing <<n>> for
// every expression, producing trivially wrong answers. avg visible span token
// length was 1.07; all 49 examples returned single-variable extractions.
//
// Fix: lazy close gated on |currentConstrainedOut| >= minSpanTokens (= 3).
// When the span is complete but shorter than 3 tokens, we call
// AdaptiveConstrainedStep again, which is forced by the parser to choose a
// continuation operator (+, -, *, /, //, %, open-paren, etc.). This causes
// the model to extend <<n>> into <<n - n1*w1 - n2*w2 - int(n3*w3)>> or similar
// before the span is allowed to close.
//
// Guidance steers the LM away from single-variable span content and toward
// writing complete multi-operator formulas in each <<...>>, with the last
// span being the complete final-answer formula.
//
// Multi-span protocol is preserved: the model may write intermediate spans
// during reasoning; the evaluator extracts the LAST span as the answer.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity  (`insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`):
//
//   Unconstrained branch: while !insideConstrainedOut the implication is vacuously
//   true. When RenderedEndsWith(generated,"<<") fires we set currentConstrainedOut := []
//   and parser.IsValidPrefix([]) holds by precondition, re-establishing the invariant.
//
//   Lazy-close branch (|currentConstrainedOut| >= minSpanTokens && IsCompletePrefix):
//   CloseConstrainedSpan sets insideConstrainedOut := false, making the implication
//   vacuously true, and clears currentConstrainedOut to [].
//
//   Constrained generation branch: AdaptiveConstrainedStep returns either eosToken
//   or a token t such that parser.IsValidPrefix(currentConstrainedOut + [t]). On EOS
//   we break (invariant vacuously maintained). Otherwise AppendConstrainedToken extends
//   currentConstrainedOut by exactly t, preserving IsValidPrefix at the new prefix.
//
// progress  (`|generated| <= |generatedPrefix| + steps`):
//
//   Unconstrained branch: steps increments by 1; generated grows by at most 1 token
//   (EOS is not appended; a "<<" token counts as exactly 1 visible token). Bound preserved.
//
//   Lazy-close branch: steps increments by 1; CloseConstrainedSpan appends at most 1
//   delimiter token (">>"). Visible growth = 1 = steps growth. Bound preserved.
//
//   Constrained generation branch: steps increments by 1; AdaptiveConstrainedStep
//   costs exactly 1 step. AppendConstrainedToken appends at most 1 visible expression
//   token. Visible growth <= 1 = steps growth. Bound preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Solve step by step in plain prose. When you write a symbolic quantity inside << >>, write the COMPLETE multi-variable formula, NEVER a bare variable name. E.g. write <<n1*w1>> not <<n1>>. Each <<...>> must contain an expression with at least one arithmetic operator (+,-,*,/,//,%,(  ),int()) connecting named problem variables and/or numbers. End with exactly: The final answer is <<FULL_FORMULA>> where FULL_FORMULA is a single complete expression combining ALL relevant problem variables.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var minSpanTokens: nat := 3;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
    // Span is long enough (>= 3 tokens) and parses as complete — close it.
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    // Inside span: either not yet complete, or complete but too short to close.
    // Generate the next parser-valid token; the parser will offer continuation
    // operators (+, -, *, /, //, %, '(' , 'int', ...) after any complete subexpression,
    // forcing the model to extend single-variable stubs into full formulas.
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

